36	namespace Slic3r::GUI::JusPrin::Agent {
37	
38	// The application JusPrin 2 is registered as on the JusPrin server: a public
39	// client using the authorization code grant, added by hand in the server's
40	// admin like v1's "JusPrin" application.
41	inline constexpr const char* kCloudClientId = "JusPrin2";
42	// The loopback port the browser is sent back to. Fixed, because OrcaSlicer's
43	// loopback server takes a port, not one the system picks; any port is
44	// accepted by the server.
45	inline constexpr unsigned short kCloudCallbackPort = 41172;
46	
47	struct CloudAuthorization
48	{
49	    std::string    authorize_url; // the page the browser opens
50	    std::string    token_url;
51	    std::string    client_id;
52	    std::string    redirect_uri;
53	    std::string    scope;
54	    std::string    state;
55	    std::string    code_verifier;
56	    unsigned short port{0};
57	    // Where the browser is sent once the app has the token, or failed to get it.
58	    std::string    success_url;
59	    std::string    failure_url;
60	};
61	
62	struct CloudAuthorizationResult
63	{
64	    bool        ok{false};
65	    std::string access_token;
66	    std::string error; // for the log; the page shows its own words
67	};
68	
69	struct CloudHttpResult
70	{
71	    unsigned    status{0}; // 0 when the request never got an answer
72	    std::string body;
73	};
74	
75	// What signing in needs from the machine.
76	struct CloudAccountDeps
77	{
78	    // Opens the browser on the authorize page and waits for its redirect on
79	    // the loopback port; `done` is called once, with the token exchange's
80	    // result. False when the loopback port could not be opened.
81	    std::function<bool(const CloudAuthorization&, std::function<void(CloudAuthorizationResult)> done)> authorize;
82	    // Stops waiting; `done` is then not called.
83	    std::function<void()> cancel_authorize;
84	    // Called from every poll(), on the owner's thread: lets the machine side
85	    // finish there what it started (OrcaSlicer's job worker finalizes its
86	    // jobs on the thread that asks it to).
87	    std::function<void()> pump;
88	    // A GET with the token as bearer; `done` is called once.
89	    std::function<void(const std::string& url, const std::string& token, std::function<void(CloudHttpResult)> done)> get;
90	    // A POST of a JSON body, with no bearer token; `session` is sent as
91	    // allauth's X-Session-Token when not empty. `done` is called once.
92	    std::function<void(const std::string& url, const std::string& body, const std::string& session,
93	                       std::function<void(CloudHttpResult)> done)>
94	        post;
95	    // Revokes a token on the server, best effort: nothing waits for it.
96	    std::function<void(const std::string& url, const std::string& client_id, const std::string& token)> revoke;
97	    // A PKCE verifier, its S256 challenge and a state value, fresh each call.
98	    std::function<void(std::string& verifier, std::string& challenge, std::string& state)> pkce;
99	};
100	
101	// The account as JusPrin keeps it on this computer.
102	struct CloudAccountRecord
103	{
104	    std::string token;
105	    std::string email;
106	    // Each model the account was last told about, with its wire format.
107	    std::vector<std::pair<std::string, std::string>> formats;
108	};
109	
110	// Where the account is kept, injected so this file never reaches AppConfig.
111	struct CloudAccountStore
112	{
113	    std::function<std::optional<CloudAccountRecord>()> load;
114	    // Stores a verified account and records the choices that make it the
115	    // Agent's provider. False when it could not be written.
116	    std::function<bool(const CloudAccountRecord&)> save;
117	    std::function<bool()> erase;
118	};
119	
120	enum class CloudSignInPhase { Idle, Browser, Email, Checking };
121	
122	// Where the browser starts: Google's sign-in, which comes back to the server
123	// and on to the app, or the server's own sign-in page, which offers email and
124	// Google both.
125	enum class CloudBrowserStart { Google, SignInPage };
126	
127	// The email sign-in, while the phase is Email.
128	struct CloudEmailStep
129	{
130	    // Choose: the person picks a code or types the password. Code: a code
131	    // was sent and the app waits for it.
132	    enum class Step { Choose, Code };
133	    Step        step{Step::Choose};
134	    std::string email;
135	    // A code, a password or a request for a code is with the server.
136	    bool        busy{false};
137	    // The server's refusal of the last try: "wrong_code", "expired_code"
138	    // (the code no longer works: it expired or was tried too often),
139	    // "too_many_codes", "wrong_password" or "too_many_tries" (passwords).
140	    // Empty when there is none.
141	    std::string refusal;
142	    // A new code went out because the person asked for one.
143	    bool        code_resent{false};
144	
145	    bool operator==(const CloudEmailStep& other) const
146	    {
147	        return step == other.step && email == other.email && busy == other.busy && refusal == other.refusal &&
148	               code_resent == other.code_resent;
149	    }
150	    bool operator!=(const CloudEmailStep& other) const { return !(*this == other); }
151	};
152	
153	struct CloudSignInOutcome
154	{
155	    enum class Kind { SignedIn, Expired, Failed };
156	    Kind            kind{Kind::Failed};
157	    std::string     email;
158	    // SignedIn: whether the account could be stored on this computer.
159	    bool            saved{false};
160	    // SignedIn: the agent for the account's default model, idle.
161	    AgentServicePtr service;
162	    // Failed: what went wrong.
163	    AgentError      error;
164	};
165	
166	class ICloudSignIn
167	{
168	public:
169	    virtual ~ICloudSignIn() = default;
170	
171	    virtual CloudSignInPhase phase() const = 0;
172	    // The page the browser was sent to, while the phase is Browser, for a
173	    // person whose browser did not open.
174	    virtual std::string browser_url() const = 0;
175	
176	    // Opens the browser at `where`. False while a sign-in or check is running,
177	    // or when the loopback port could not be opened.
178	    virtual bool start(CloudBrowserStart where) = 0;
179	    // Checks the token already stored: the account's email and model formats
180	    // are refreshed, or the token turns out to have expired. False when no
181	    // token is stored or something is already running.
182	    virtual bool check_stored() = 0;
183	    virtual void cancel() = 0;
184	    virtual std::optional<CloudSignInOutcome> poll() = 0;
185	
186	    // Signing in by email. Each is false when the step does not take it.
187	    virtual std::optional<CloudEmailStep> email_step() const = 0;
188	    // From Idle: the address the person typed; nothing is sent yet.
189	    virtual bool start_email(const std::string& email) = 0;
190	    // Asks the server to email a code, or a new one from the code step.
191	    virtual bool send_code() = 0;
192	    virtual bool submit_code(const std::string& code) = 0;
193	    virtual bool submit_password(const std::string& password) = 0;
194	
195	    // The stored account, or nothing when signed out.
196	    virtual std::optional<CloudAccountRecord> account() const = 0;
197	    // Forgets the account on this computer and revokes its token. False when
198	    // there was none or it could not be removed.
199	    virtual bool sign_out() = 0;
200	};
201	
202	using CloudSignInPtr = std::shared_ptr<ICloudSignIn>;
203	
204	class CloudSignIn final : public ICloudSignIn
205	{
206	public:
207	    // Builds the agent for a verified account: its token, the model and that
208	    // model's wire format.
209	    using AgentFactory = std::function<AgentServicePtr(const std::string& token, const std::string& model,
210	                                                       const std::string& format)>;
211	
212	    // `server` is the JusPrin server's base URL, as "https://jusprinv2.obico.io";
213	    // `gateway` is the provider's request endpoint, whose sibling "models"
214	    // lists the account's models.
215	    CloudSignIn(std::string server, std::string gateway, std::string default_model, CloudAccountDeps deps,
216	                CloudAccountStore store, AgentFactory agents);
217	    ~CloudSignIn() override;
218	
219	    CloudSignInPhase                  phase() const override { return m_phase; }
220	    std::string                       browser_url() const override;
221	    bool                              start(CloudBrowserStart where) override;
222	    bool                              check_stored() override;
223	    void                              cancel() override;
224	    std::optional<CloudSignInOutcome> poll() override;
225	    std::optional<CloudEmailStep>     email_step() const override;
226	    bool                              start_email(const std::string& email) override;
227	    bool                              submit_code(const std::string& code) override;
228	    bool                              submit_password(const std::string& password) override;
229	    bool                              send_code() override;
230	    std::optional<CloudAccountRecord> account() const override;
231	    bool                              sign_out() override;
232	
233	private:
234	    struct Inbox;
235	
236	    void begin_check(std::string token);
237	    void ask_server(const std::string& endpoint, const nlohmann::json& body, const std::string& session);
238	    std::optional<CloudSignInOutcome> answered(CloudHttpResult http);
239	    void ask_who(std::uint64_t generation);
240	    void ask_models(std::uint64_t generation);
241	    std::optional<CloudSignInOutcome> finish_check();
242	    CloudSignInOutcome failed(const std::string& code, const std::string& message, bool retryable);
243	
244	    std::string                    m_server;
245	    std::string                    m_gateway;
246	    std::string                    m_default_model;
247	    CloudAccountDeps               m_deps;
248	    CloudAccountStore              m_store;
249	    AgentFactory                   m_agents;
250	    std::shared_ptr<Inbox>         m_inbox;
251	    CloudSignInPhase               m_phase{CloudSignInPhase::Idle};
252	    std::uint64_t                  m_generation{0};
253	    CloudAuthorization             m_authorization;
254	    // The check in progress: the token being checked, and what the server
255	    // has said so far.
256	    std::string                    m_token;
257	    CloudEmailStep                 m_email;
258	    // allauth's session token between the email steps.
259	    std::string                    m_session;
260	    // The auth endpoint the request in flight went to.
261	    std::string                    m_asked;
262	    std::optional<CloudHttpResult> m_who;
263	    std::optional<CloudHttpResult> m_models;
264	};
265	
266	// The JusPrin server a token comes from and goes back to, from its gateway
267	// endpoint: everything before "/ent/".
268	std::string cloud_server_from_gateway(const std::string& gateway);
269	
270	} // namespace Slic3r::GUI::JusPrin::Agent
