16	std::string percent_encoded(const std::string& text)
17	{
18	    std::string encoded;
19	    for (const unsigned char c : text) {
20	        if (std::isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') {
21	            encoded += static_cast<char>(c);
22	        } else {
23	            char escaped[4];
24	            std::snprintf(escaped, sizeof(escaped), "%%%02X", c);
25	            encoded += escaped;
26	        }
27	    }
28	    return encoded;
29	}
30	
31	std::string query(const std::vector<std::pair<std::string, std::string>>& parameters)
32	{
33	    std::string text;
34	    for (const auto& [name, value] : parameters)
35	        text += (text.empty() ? "" : "&") + name + "=" + percent_encoded(value);
36	    return text;
37	}
38	
39	bool refused(const CloudHttpResult& result) { return result.status == 401 || result.status == 403; }
40	
41	} // namespace
