43	// What the injected browser and HTTP calls report, queued until poll(). Shared
44	// with the callbacks so one that arrives after this object is gone has
45	// somewhere harmless to go.
46	struct CloudSignIn::Inbox
47	{
48	    enum class Kind { Authorized, Who, Models, Auth };
49	    struct Item
50	    {
51	        std::uint64_t            generation{0};
52	        Kind                     kind{Kind::Authorized};
53	        CloudAuthorizationResult authorization;
54	        CloudHttpResult          http;
55	    };
56	    std::mutex       mutex;
57	    std::deque<Item> items;
58	
59	    void push(Item item)
60	    {
61	        std::lock_guard<std::mutex> lock(mutex);
62	        items.push_back(std::move(item));
63	    }
64	    std::optional<Item> pop()
65	    {
66	        std::lock_guard<std::mutex> lock(mutex);
67	        if (items.empty())
68	            return std::nullopt;
69	        Item item = std::move(items.front());
70	        items.pop_front();
71	        return item;
72	    }
73	};
74	
75	std::string cloud_server_from_gateway(const std::string& gateway)
76	{
77	    const std::size_t ent = gateway.find("/ent/");
78	    if (ent != std::string::npos)
79	        return gateway.substr(0, ent);
80	    const std::size_t scheme = gateway.find("://");
81	    const std::size_t path   = gateway.find('/', scheme == std::string::npos ? 0 : scheme + 3);
82	    return path == std::string::npos ? gateway : gateway.substr(0, path);
83	}
84	
85	CloudSignIn::CloudSignIn(std::string server, std::string gateway, std::string default_model, CloudAccountDeps deps,
86	                         CloudAccountStore store, AgentFactory agents)
87	    : m_server(std::move(server)), m_gateway(std::move(gateway)), m_default_model(std::move(default_model)),
88	      m_deps(std::move(deps)), m_store(std::move(store)), m_agents(std::move(agents)), m_inbox(std::make_shared<Inbox>())
89	{}
90	
91	CloudSignIn::~CloudSignIn() { cancel(); }
92	
93	std::string CloudSignIn::browser_url() const
94	{
95	    return m_phase == CloudSignInPhase::Browser ? m_authorization.authorize_url : std::string();
96	}
