98	bool CloudSignIn::start(CloudBrowserStart where)
99	{
100	    if (m_phase != CloudSignInPhase::Idle)
101	        return false;
102	    std::string verifier, challenge, state;
103	    m_deps.pkce(verifier, challenge, state);
104	    CloudAuthorization authorization;
105	    authorization.client_id     = kCloudClientId;
106	    authorization.port          = kCloudCallbackPort;
107	    authorization.redirect_uri  = "http://127.0.0.1:" + std::to_string(kCloudCallbackPort) + "/callback";
108	    authorization.scope         = "read write";
109	    authorization.state         = state;
110	    authorization.code_verifier = verifier;
111	    authorization.token_url     = m_server + "/o/token/";
112	    authorization.success_url   = m_server + "/ent/jusprin/v2/signed_in/";
113	    authorization.failure_url   = m_server + "/ent/jusprin/v2/sign_in_failed/";
114	    const std::string authorize = "/o/authorize/?" + query({{"response_type", "code"},
115	                                                            {"client_id", authorization.client_id},
116	                                                            {"redirect_uri", authorization.redirect_uri},
117	                                                            {"scope", authorization.scope},
118	                                                            {"state", state},
119	                                                            {"code_challenge", challenge},
120	                                                            {"code_challenge_method", "S256"}});
121	    // Google's sign-in comes back to the server, which then sends the browser
122	    // on to /o/authorize/, now signed in. Opened directly, /o/authorize/ first
123	    // shows the server's sign-in page.
124	    authorization.authorize_url = where == CloudBrowserStart::Google ?
125	                                      m_server + "/accounts/google/login/?" +
126	                                          query({{"process", "login"}, {"next", authorize}}) :
127	                                      m_server + authorize;
128	
129	    const std::uint64_t generation = ++m_generation;
130	    std::weak_ptr<Inbox> inbox     = m_inbox;
131	    if (!m_deps.authorize(authorization, [inbox, generation](CloudAuthorizationResult result) {
132	            if (const auto target = inbox.lock())
133	                target->push({generation, Inbox::Kind::Authorized, std::move(result), {}});
134	        }))
135	        return false;
136	    m_authorization = std::move(authorization);
137	    m_phase         = CloudSignInPhase::Browser;
138	    return true;
139	}
140	
141	bool CloudSignIn::check_stored()
142	{
143	    if (m_phase != CloudSignInPhase::Idle || !m_store.load)
144	        return false;
145	    const std::optional<CloudAccountRecord> record = m_store.load();
146	    if (!record || record->token.empty())
147	        return false;
148	    ++m_generation;
149	    begin_check(record->token);
150	    return true;
151	}
152	
153	void CloudSignIn::begin_check(std::string token)
154	{
155	    m_phase = CloudSignInPhase::Checking;
156	    m_token = std::move(token);
157	    m_who.reset();
158	    m_models.reset();
159	    ask_who(m_generation);
160	    ask_models(m_generation);
161	}
162	
163	void CloudSignIn::ask_who(std::uint64_t generation)
164	{
165	    std::weak_ptr<Inbox> inbox = m_inbox;
166	    m_deps.get(m_server + "/jusprin/api/me/", m_token, [inbox, generation](CloudHttpResult result) {
167	        if (const auto target = inbox.lock())
168	            target->push({generation, Inbox::Kind::Who, {}, std::move(result)});
169	    });
170	}
171	
172	void CloudSignIn::ask_models(std::uint64_t generation)
173	{
174	    const std::size_t    slash = m_gateway.rfind('/');
175	    const std::string    url   = (slash == std::string::npos ? m_gateway : m_gateway.substr(0, slash)) + "/models";
176	    std::weak_ptr<Inbox> inbox = m_inbox;
177	    m_deps.get(url, m_token, [inbox, generation](CloudHttpResult result) {
178	        if (const auto target = inbox.lock())
179	            target->push({generation, Inbox::Kind::Models, {}, std::move(result)});
180	    });
181	}
182	
183	std::optional<CloudEmailStep> CloudSignIn::email_step() const
184	{
185	    if (m_phase != CloudSignInPhase::Email)
186	        return std::nullopt;
187	    return m_email;
188	}
189	
190	void CloudSignIn::ask_server(const std::string& endpoint, const json& body, const std::string& session)
191	{
192	    m_asked             = endpoint;
193	    m_email.busy        = true;
194	    m_email.refusal.clear();
195	    std::weak_ptr<Inbox> inbox = m_inbox;
196	    const std::uint64_t generation = m_generation;
197	    m_deps.post(m_server + "/ent/jusprin/v2/auth/" + endpoint, body.dump(), session,
198	                [inbox, generation](CloudHttpResult result) {
199	                    if (const auto target = inbox.lock())
200	                        target->push({generation, Inbox::Kind::Auth, {}, std::move(result)});
201	                });
202	}
203	
204	bool CloudSignIn::start_email(const std::string& email)
205	{
206	    if (m_phase != CloudSignInPhase::Idle || email.empty())
207	        return false;
208	    ++m_generation;
209	    m_phase       = CloudSignInPhase::Email;
210	    m_email       = CloudEmailStep{};
211	    m_email.email = email;
212	    m_session.clear();
213	    return true;
214	}
215	
216	bool CloudSignIn::send_code()
217	{
218	    if (m_phase != CloudSignInPhase::Email || m_email.busy)
219	        return false;
220	    // A new request rather than allauth's resend: a resent code keeps the
221	    // first one's deadline and is refused once that code is spent. The
222	    // pending code's session stays until the new one's arrives, in case the
223	    // server refuses to send another.
224	    ask_server("code/request", {{"email", m_email.email}}, {});
225	    return true;
226	}
227	
228	bool CloudSignIn::submit_code(const std::string& code)
229	{
230	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Code)
231	        return false;
232	    ask_server("code/confirm", {{"code", code}}, m_session);
233	    return true;
234	}
235	
236	bool CloudSignIn::submit_password(const std::string& password)
237	{
238	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Choose)
239	        return false;
240	    // The server signs in by username; allauth matches it against addresses too.
241	    ask_server("login", {{"username", m_email.email}, {"password", password}}, {});
242	    return true;
243	}
