245	// What an auth endpoint answered, in allauth's shapes: 200 once signed in,
246	// with the token in "meta"; 401 while a code is pending, with the session
247	// token to carry; 400 with "errors"; 409 once the pending code is gone. A
248	// token goes on to the same check as the browser's; a refusal the person can
249	// act on stays on the step; anything else ends the sign-in with one generic
250	// error.
251	std::optional<CloudSignInOutcome> CloudSignIn::answered(CloudHttpResult http)
252	{
253	    m_email.busy = false;
254	    const json body   = json::parse(http.body, nullptr, false);
255	    const auto errors = [&](const char* code) {
256	        if (!body.is_object() || !body.contains("errors") || !body["errors"].is_array())
257	            return false;
258	        return std::any_of(body["errors"].begin(), body["errors"].end(),
259	                           [code](const json& error) { return error.is_object() && error.value("code", "") == code; });
260	    };
261	    const std::string session = body.is_object() ? body.value("/meta/session_token"_json_pointer, std::string()) : std::string();
262	    const std::string token   = body.is_object() ? body.value("/meta/access_token"_json_pointer, std::string()) : std::string();
263	
264	    if (m_asked == "code/request" && http.status == 401 && !session.empty()) {
265	        m_email.code_resent = m_email.step == CloudEmailStep::Step::Code;
266	        m_email.step        = CloudEmailStep::Step::Code;
267	        m_session           = session;
268	        return std::nullopt;
269	    }
270	    if (http.status == 200 && !token.empty()) {
271	        m_session.clear();
272	        begin_check(token);
273	        return std::nullopt;
274	    }
275	    if (http.status == 400 && m_asked == "code/request" && errors("too_many_login_attempts"))
276	        m_email.refusal = "too_many_codes";
277	    else if (http.status == 400 && m_asked == "code/confirm" && errors("incorrect_code"))
278	        m_email.refusal = "wrong_code";
279	    else if (http.status == 409 && m_asked == "code/confirm")
280	        m_email.refusal = "expired_code";
281	    else if (http.status == 400 && m_asked == "login")
282	        m_email.refusal = errors("too_many_login_attempts") ? "too_many_tries" : "wrong_password";
283	    else
284	        return failed("sign_in_failed", "JusPrin couldn't sign you in. Try again.", true);
285	    return std::nullopt;
286	}
287	
288	void CloudSignIn::cancel()
289	{
290	    if (m_phase == CloudSignInPhase::Browser && m_deps.cancel_authorize)
291	        m_deps.cancel_authorize();
292	    ++m_generation;
293	    m_phase = CloudSignInPhase::Idle;
294	    m_token.clear();
295	    m_session.clear();
296	    m_who.reset();
297	    m_models.reset();
298	}
299	
300	std::optional<CloudSignInOutcome> CloudSignIn::poll()
301	{
302	    if (m_deps.pump)
303	        m_deps.pump();
304	    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
305	        if (item->generation != m_generation)
306	            continue; // from a sign-in that was cancelled
307	        switch (item->kind) {
308	        case Inbox::Kind::Authorized:
309	            if (m_phase != CloudSignInPhase::Browser)
310	                continue;
311	            if (!item->authorization.ok || item->authorization.access_token.empty())
312	                return failed("sign_in_failed", "Signing in didn't finish. Nothing was saved. Try again.", true);
313	            begin_check(std::move(item->authorization.access_token));
314	            break;
315	        case Inbox::Kind::Auth:
316	            if (m_phase != CloudSignInPhase::Email)
317	                continue;
318	            if (std::optional<CloudSignInOutcome> outcome = answered(std::move(item->http)))
319	                return outcome;
320	            break;
321	        case Inbox::Kind::Who: m_who = std::move(item->http); break;
322	        case Inbox::Kind::Models: m_models = std::move(item->http); break;
323	        }
324	        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
325	            return finish_check();
326	    }
327	    return std::nullopt;
328	}
329	
330	std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
331	{
332	    const CloudHttpResult who    = std::move(*m_who);
333	    const CloudHttpResult models = std::move(*m_models);
334	    m_who.reset();
335	    m_models.reset();
336	    if (refused(who) || refused(models)) {
337	        m_phase = CloudSignInPhase::Idle;
338	        m_token.clear();
339	        CloudSignInOutcome outcome;
340	        outcome.kind = CloudSignInOutcome::Kind::Expired;
341	        return outcome;
342	    }
343	    const json who_json    = json::parse(who.body, nullptr, false);
344	    const json models_json = json::parse(models.body, nullptr, false);
345	    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
346	        !models_json.contains("data"))
347	        return failed("account_unreachable", "JusPrin couldn't be reached to finish signing in. Try again.", true);
348	
349	    CloudAccountRecord record;
350	    record.token = m_token;
351	    // /jusprin/api/me/ answers {"user": {"email", ...}, "ai_credits": {...}}.
352	    record.email = who_json.value("/user/email"_json_pointer, std::string());
353	    for (const json& entry : models_json["data"]) {
354	        const std::string id = entry.value("id", ""), format = entry.value("format", "");
355	        if (!id.empty() && !format.empty())
356	            record.formats.emplace_back(id, format);
357	    }
358	    // The agent is for the provider's default model, or else the first the
359	    // server lists.
360	    auto chosen = std::find_if(record.formats.begin(), record.formats.end(),
361	                               [this](const auto& entry) { return entry.first == m_default_model; });
362	    if (chosen == record.formats.end())
363	        chosen = record.formats.begin();
364	    AgentServicePtr service = chosen == record.formats.end() ? nullptr : m_agents(m_token, chosen->first, chosen->second);
365	    if (!service)
366	        return failed("account_no_models", "JusPrin has no Agent model for this account right now. Try again later.", true);
367	
368	    CloudSignInOutcome outcome;
369	    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
370	    outcome.email   = record.email;
371	    outcome.saved   = m_store.save && m_store.save(record);
372	    outcome.service = std::move(service);
373	    m_phase         = CloudSignInPhase::Idle;
374	    m_token.clear();
375	    return outcome;
376	}
377	
378	CloudSignInOutcome CloudSignIn::failed(const std::string& code, const std::string& message, bool retryable)
379	{
380	    m_phase = CloudSignInPhase::Idle;
381	    m_token.clear();
382	    CloudSignInOutcome outcome;
383	    outcome.kind  = CloudSignInOutcome::Kind::Failed;
384	    outcome.error = AgentError{code, message, retryable};
385	    return outcome;
386	}
387	
388	std::optional<CloudAccountRecord> CloudSignIn::account() const
389	{
390	    if (!m_store.load)
391	        return std::nullopt;
392	    std::optional<CloudAccountRecord> record = m_store.load();
393	    if (!record || record->token.empty())
394	        return std::nullopt;
395	    return record;
396	}
397	
398	bool CloudSignIn::sign_out()
399	{
400	    const std::optional<CloudAccountRecord> record = account();
401	    if (!record || !m_store.erase || !m_store.erase())
402	        return false;
403	    cancel();
404	    if (m_deps.revoke)
405	        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
406	    return true;
407	}
