98	bool CloudSignIn::start(CloudBrowserStart where)
99	{
100	    if (m_phase != CloudSignInPhase::Idle)
101	        return false;
102	    std::string verifier, challenge, state;
103	    m_deps.pkce(verifier, challenge, state);
104	    CloudAuthorization authorization;
105	    authorization.client_id     = kCloudClientId;
106	    authorization.port          = kCloudCallbackPort;
107	    authorization.redirect_uri  = "http://127.0.0.1:" + std::to_string(kCloudCallbackPort) + "/callback";
108	    authorization.scope         = "read write";
109	    authorization.state         = state;
110	    authorization.code_verifier = verifier;
111	    authorization.token_url     = m_server + "/o/token/";
112	    authorization.success_url   = m_server + "/ent/jusprin/v2/signed_in/";
113	    authorization.failure_url   = m_server + "/ent/jusprin/v2/sign_in_failed/";
114	    const std::string authorize = "/o/authorize/?" + query({{"response_type", "code"},
115	                                                            {"client_id", authorization.client_id},
116	                                                            {"redirect_uri", authorization.redirect_uri},
117	                                                            {"scope", authorization.scope},
118	                                                            {"state", state},
119	                                                            {"code_challenge", challenge},
120	                                                            {"code_challenge_method", "S256"}});
121	    // Google's sign-in comes back to the server, which then sends the browser
122	    // on to /o/authorize/, now signed in. Opened directly, /o/authorize/ first
123	    // shows the server's sign-in page.
124	    authorization.authorize_url = where == CloudBrowserStart::Google ?
125	                                      m_server + "/accounts/google/login/?" +
126	                                          query({{"process", "login"}, {"next", authorize}}) :
127	                                      m_server + authorize;
128	
129	    const std::uint64_t generation = ++m_generation;
130	    std::weak_ptr<Inbox> inbox     = m_inbox;
131	    if (!m_deps.authorize(authorization, [inbox, generation](CloudAuthorizationResult result) {
132	            if (const auto target = inbox.lock())
133	                target->push({generation, Inbox::Kind::Authorized, std::move(result), {}});
134	        }))
135	        return false;
136	    m_authorization = std::move(authorization);
137	    m_phase         = CloudSignInPhase::Browser;
138	    return true;
139	}
