216	bool CloudSignIn::send_code()
217	{
218	    if (m_phase != CloudSignInPhase::Email || m_email.busy)
219	        return false;
220	    // A new request rather than allauth's resend: a resent code keeps the
221	    // first one's deadline and is refused once that code is spent. The
222	    // pending code's session stays until the new one's arrives, in case the
223	    // server refuses to send another.
224	    ask_server("code/request", {{"email", m_email.email}}, {});
225	    return true;
226	}
