300	std::optional<CloudSignInOutcome> CloudSignIn::poll()
301	{
302	    if (m_deps.pump)
303	        m_deps.pump();
304	    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
305	        if (item->generation != m_generation)
306	            continue; // from a sign-in that was cancelled
307	        switch (item->kind) {
308	        case Inbox::Kind::Authorized:
309	            if (m_phase != CloudSignInPhase::Browser)
310	                continue;
311	            if (!item->authorization.ok || item->authorization.access_token.empty())
312	                return failed("sign_in_failed", "Signing in didn't finish. Nothing was saved. Try again.", true);
313	            begin_check(std::move(item->authorization.access_token));
314	            break;
315	        case Inbox::Kind::Auth:
316	            if (m_phase != CloudSignInPhase::Email)
317	                continue;
318	            if (std::optional<CloudSignInOutcome> outcome = answered(std::move(item->http)))
319	                return outcome;
320	            break;
321	        case Inbox::Kind::Who: m_who = std::move(item->http); break;
322	        case Inbox::Kind::Models: m_models = std::move(item->http); break;
323	        }
324	        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
325	            return finish_check();
326	    }
327	    return std::nullopt;
328	}
329	
330	std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
331	{
332	    const CloudHttpResult who    = std::move(*m_who);
333	    const CloudHttpResult models = std::move(*m_models);
334	    m_who.reset();
335	    m_models.reset();
336	    if (refused(who) || refused(models)) {
337	        m_phase = CloudSignInPhase::Idle;
338	        m_token.clear();
339	        CloudSignInOutcome outcome;
340	        outcome.kind = CloudSignInOutcome::Kind::Expired;
341	        return outcome;
342	    }
343	    const json who_json    = json::parse(who.body, nullptr, false);
344	    const json models_json = json::parse(models.body, nullptr, false);
345	    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
346	        !models_json.contains("data"))
347	        return failed("account_unreachable", "JusPrin couldn't be reached to finish signing in. Try again.", true);
348	
349	    CloudAccountRecord record;
350	    record.token = m_token;
351	    // /jusprin/api/me/ answers {"user": {"email", ...}, "ai_credits": {...}}.
352	    record.email = who_json.value("/user/email"_json_pointer, std::string());
353	    for (const json& entry : models_json["data"]) {
354	        const std::string id = entry.value("id", ""), format = entry.value("format", "");
355	        if (!id.empty() && !format.empty())
356	            record.formats.emplace_back(id, format);
357	    }
358	    // The agent is for the provider's default model, or else the first the
359	    // server lists.
360	    auto chosen = std::find_if(record.formats.begin(), record.formats.end(),
361	                               [this](const auto& entry) { return entry.first == m_default_model; });
362	    if (chosen == record.formats.end())
363	        chosen = record.formats.begin();
364	    AgentServicePtr service = chosen == record.formats.end() ? nullptr : m_agents(m_token, chosen->first, chosen->second);
365	    if (!service)
366	        return failed("account_no_models", "JusPrin has no Agent model for this account right now. Try again later.", true);
367	
368	    CloudSignInOutcome outcome;
369	    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
370	    outcome.email   = record.email;
371	    outcome.saved   = m_store.save && m_store.save(record);
372	    outcome.service = std::move(service);
373	    m_phase         = CloudSignInPhase::Idle;
374	    m_token.clear();
375	    return outcome;
376	}
