80	// Deletes a provider's stored key, and an account's email and formats with
81	// it. A chat without a choice of its own talks to the recorded provider; once
82	// its key is gone, that is the first provider that still has one.
83	bool remove_provider_key(AppConfig* config, const std::string& provider)
84	{
85	    if (config == nullptr || config->get(kSection, api_key_item_for(provider)).empty())
86	        return false;
87	    config->erase(kSection, api_key_item_for(provider));
88	    config->erase(kSection, account_item_for(provider));
89	    config->erase(kSection, formats_item_for(provider));
90	    if (config->get(kSection, "provider") == provider)
91	        for (const ProviderProfile& profile : provider_profiles())
92	            if (!config->get(kSection, api_key_item_for(profile.id)).empty()) {
93	                config->set(kSection, "provider", profile.id);
94	                break;
95	            }
96	    // Saved now, as a stored key is: the person was just told it is gone.
97	    config->save();
98	    return true;
99	}
