128	AgentRuntime load_agent_runtime(AppConfig* config)
129	{
130	    AgentSettings settings;
131	    settings.enabled       = configured_true(config, "enabled");
132	    settings.cloud_consent = configured_true(config, "cloud_consent");
133	    if (config != nullptr) {
134	        settings.provider = config->get(kSection, "provider");
135	        settings.model    = config->get(kSection, "model");
136	    }
137	    settings.api_key = load_provider_api_key(config, settings.provider.empty() ? "openai" : settings.provider);
138	    if (const ProviderProfile* profile = profile_for(settings.provider); profile != nullptr && profile->account_sign_in) {
139	        settings.format   = stored_format(config, profile->id, settings.model.empty() ? profile->model : settings.model);
140	        settings.endpoint = cloud_gateway(config, *profile);
