147	AgentSetupServicePtr make_agent_setup(AppConfig* config)
148	{
149	    // Committing is the only part of setup that touches the machine, so it
150	    // lives here rather than in the GUI-free probe. Reaching this point means
151	    // the user read what the dock says about the provider billing them and
152	    // about the key staying on this machine, and chose to continue: that is
153	    // the cloud consent load_agent_runtime() requires on the next launch.
154	    auto commit = [config](const SetupCredentials& credentials) {
155	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
156	            return false;
157	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
158	        config->set(kSection, "provider", credentials.provider);
159	        config->set(kSection, "enabled", "true");
160	        config->set(kSection, "cloud_consent", "true");
161	        if (!credentials.model.empty())
162	            config->set(kSection, "model", credentials.model);
163	        // Written now, not at the next routine save, so a crash after setup
164	        // does not lose a key the user was just told is stored.
165	        config->save();
166	        return true;
167	    };
168	    ProviderKeySetup::KeyStore keys;
169	    keys.load   = [config](const std::string& provider) { return load_provider_api_key(config, provider); };
170	    keys.remove = [config](const std::string& provider) { return remove_provider_key(config, provider); };
171	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit), std::move(keys),
172	                                              agent_endpoint_override(), ProviderKeySetup::Clock{},
173	                                              make_cloud_sign_in(config));
174	}
