196	CloudSignInPtr make_cloud_sign_in(AppConfig* config)
197	{
198	    const ProviderProfile& row     = account_provider();
199	    const std::string      gateway = endpoint_for(config, row);
200	    CloudAccountStore      store;
201	    store.load = [config, id = row.id]() -> std::optional<CloudAccountRecord> {
202	        if (config == nullptr)
203	            return std::nullopt;
204	        CloudAccountRecord record;
205	        record.token   = config->get(kSection, api_key_item_for(id));
206	        record.email   = config->get(kSection, account_item_for(id));
207	        record.formats = stored_formats(config, id);
208	        return record;
209	    };
210	    // Signing in is choosing the account as the Agent's provider, after the
211	    // account row told the person what goes to JusPrin and on to the model's
212	    // provider: the same choices and consent a verified key records.
213	    store.save = [config, id = row.id](const CloudAccountRecord& record) {
214	        if (config == nullptr)
215	            return false;
216	        config->set(kSection, api_key_item_for(id), record.token);
217	        config->set(kSection, account_item_for(id), record.email);
218	        store_formats(config, id, record.formats);
219	        config->set(kSection, "provider", id);
220	        config->set(kSection, "enabled", "true");
221	        config->set(kSection, "cloud_consent", "true");
222	        config->save();
223	        return true;
224	    };
225	    store.erase = [config, id = row.id]() { return remove_provider_key(config, id); };
226	    auto agents = [row, gateway](const std::string& token, const std::string& model, const std::string& format) -> AgentServicePtr {
227	        const std::optional<ProviderProfile> served = account_profile(row, gateway, format);
228	        if (!served)
229	            return nullptr;
230	        return make_provider_agent(*served, token, model, {}, make_openai_http_transport(), logging_listeners());
231	    };
232	    return std::make_shared<CloudSignIn>(cloud_server_from_gateway(gateway), gateway, row.model, make_cloud_account_deps(),
233	                                         std::move(store), std::move(agents));
234	}
