238	class AppConfigChatModelSource final : public IChatModelSource
239	{
240	public:
241	    AppConfigChatModelSource(AppConfig* config, std::function<void(std::function<void()>)> post)
242	        : m_config(config), m_post(std::move(post)), m_cancelled(std::make_shared<std::atomic<bool>>(false))
243	    {}
244	    // A list still on its way is dropped rather than delivered to a host
245	    // that is gone.
246	    ~AppConfigChatModelSource() override { *m_cancelled = true; }
247	
248	    // Read each time: setup may have stored a key since the last turn.
249	    std::vector<std::string> configured_providers() const override
250	    {
251	        std::vector<std::string> providers;
252	        if (!configured_true(m_config, "enabled") || !configured_true(m_config, "cloud_consent"))
253	            return providers;
254	        for (const ProviderProfile& profile : provider_profiles())
255	            if (!load_provider_api_key(m_config, profile.id).empty())
256	                providers.push_back(profile.id);
257	        return providers;
258	    }
259	
260	    std::string default_provider() const override
261	    {
262	        const std::string provider = m_config == nullptr ? std::string() : m_config->get(kSection, "provider");
263	        return provider.empty() ? "openai" : provider;
264	    }
265	
266	    AgentServicePtr make_agent(const ChatModelChoice& choice) override
267	    {
268	        const ProviderProfile* row = profile_for(choice.provider);
269	        const std::string      key = load_provider_api_key(m_config, choice.provider);
270	        if (row == nullptr || key.empty())
271	            return nullptr;
272	        ProviderProfile profile = *row;
273	        profile.effort          = choice.effort;
274	        if (!row->account_sign_in)
275	            return make_provider_agent(profile, key, choice.model, agent_endpoint_override(), make_openai_http_transport(),
276	                                       logging_listeners());
277	        const std::optional<ProviderProfile> served = account_profile(profile, endpoint_for(m_config, *row), choice.format);
278	        if (!served)
279	            return nullptr;
280	        return make_provider_agent(*served, key, choice.model, {}, make_openai_http_transport(), logging_listeners());
281	    }
282	
283	    std::string model_format(const std::string& provider, const std::string& model) const override
284	    {
285	        return stored_format(m_config, provider, model);
286	    }
287	
288	    void fetch_account(AccountDone done) override
289	    {
290	        for (const std::string& provider : configured_providers()) {
291	            const ProviderProfile* profile = profile_for(provider);
292	            if (profile == nullptr || !profile->account_sign_in)
293	                continue;
294	            Agent::fetch_account(*profile, load_provider_api_key(m_config, provider), endpoint_for(m_config, *profile), m_cancelled,
295	                                 [post = m_post, done = std::move(done)](std::optional<nlohmann::json> account) {
296	                                     post([done, account = std::move(account)]() mutable { done(std::move(account)); });
297	                                 });
298	            return;
299	        }
300	        done(std::nullopt);
301	    }
302	
303	    void list_models(const std::string& provider, ModelsDone done) override
304	    {
305	        const ProviderProfile* profile = profile_for(provider);
306	        const std::string      key     = load_provider_api_key(m_config, provider);
307	        if (profile == nullptr || key.empty()) {
308	            done(false, {});
309	            return;
310	        }
311	        fetch_model_list(*profile, key, endpoint_for(m_config, *profile), m_cancelled,
312	                         [post = m_post, done = std::move(done), provider, config = m_config,
313	                          account = profile->account_sign_in](ModelListResult result) {
314	                             if (!result.ok)
315	                                 BOOST_LOG_TRIVIAL(warning) << "Agent model list for " << provider << ": " << result.error;
316	                             post([done, result = std::move(result), provider, config, account]() mutable {
317	                                 // An account's list says which format each model
318	                                 // is served in now; chats not yet started go by it.
319	                                 if (account && result.ok && config != nullptr) {
320	                                     std::vector<std::pair<std::string, std::string>> formats;
321	                                     for (const ModelOption& option : result.models)
322	                                         formats.emplace_back(option.id, option.format);
323	                                     store_formats(config, provider, formats);
324	                                     config->save();
325	                                 }
326	                                 done(result.ok, std::move(result.models));
327	                             });
328	                         });
329	    }
330	
331	private:
332	    AppConfig*                                  m_config;
333	    std::function<void(std::function<void()>)>  m_post;
334	    std::shared_ptr<std::atomic<bool>>          m_cancelled;
335	};
