19	constexpr const char* kSection = "jusprin_agent";
20	
21	// A server named here, such as a staging or self-hosted one, is the one the
22	// account signs in to instead of the default. JusPrin v1 kept its own server
23	// here too; the v1 import leaves that behind.
24	constexpr const char* kServerSection = "jusprin_server";
