26	std::string api_key_item_for(const std::string& provider) { return provider + "_api_key"; }
27	// An account provider keeps the account's email and the wire format of each
28	// of its models beside the token.
29	std::string account_item_for(const std::string& provider) { return provider + "_account"; }
30	std::string formats_item_for(const std::string& provider) { return provider + "_model_formats"; }
