32	// Where an account provider's gateway is: on the server v1's setting names,
33	// or the row's own.
34	std::string cloud_gateway(const AppConfig* config, const ProviderProfile& row)
35	{
36	    std::string base = config == nullptr ? std::string() : config->get(kServerSection, "base_url");
37	    while (!base.empty() && base.back() == '/')
38	        base.pop_back();
39	    return base.empty() ? row.endpoint : base + "/ent/jusprin/v2/responses";
40	}
