42	// The endpoint a provider is reached at, where it is not the row's: the
43	// developer's override for any provider, or an account provider's gateway.
44	std::string endpoint_for(const AppConfig* config, const ProviderProfile& profile)
45	{
46	    if (std::string override_endpoint = agent_endpoint_override(); !override_endpoint.empty())
47	        return override_endpoint;
48	    return profile.account_sign_in ? cloud_gateway(config, profile) : std::string();
49	}
