51	std::vector<std::pair<std::string, std::string>> stored_formats(const AppConfig* config, const std::string& provider)
52	{
53	    std::vector<std::pair<std::string, std::string>> formats;
54	    if (config == nullptr)
55	        return formats;
56	    const nlohmann::json stored = nlohmann::json::parse(config->get(kSection, formats_item_for(provider)), nullptr, false);
57	    if (stored.is_object())
58	        for (const auto& [model, format] : stored.items())
59	            if (format.is_string())
60	                formats.emplace_back(model, format.get<std::string>());
61	    return formats;
62	}
63	
64	void store_formats(AppConfig* config, const std::string& provider, const std::vector<std::pair<std::string, std::string>>& formats)
65	{
66	    nlohmann::json stored = nlohmann::json::object();
67	    for (const auto& [model, format] : formats)
68	        stored[model] = format;
69	    config->set(kSection, formats_item_for(provider), stored.dump());
70	}
71	
72	std::string stored_format(const AppConfig* config, const std::string& provider, const std::string& model)
73	{
74	    for (const auto& [listed, format] : stored_formats(config, provider))
75	        if (listed == model)
76	            return format;
77	    return {};
78	}
