266	    AgentServicePtr make_agent(const ChatModelChoice& choice) override
267	    {
268	        const ProviderProfile* row = profile_for(choice.provider);
269	        const std::string      key = load_provider_api_key(m_config, choice.provider);
270	        if (row == nullptr || key.empty())
271	            return nullptr;
272	        ProviderProfile profile = *row;
273	        profile.effort          = choice.effort;
274	        if (!row->account_sign_in)
275	            return make_provider_agent(profile, key, choice.model, agent_endpoint_override(), make_openai_http_transport(),
276	                                       logging_listeners());
277	        const std::optional<ProviderProfile> served = account_profile(profile, endpoint_for(m_config, *row), choice.format);
278	        if (!served)
279	            return nullptr;
280	        return make_provider_agent(*served, key, choice.model, {}, make_openai_http_transport(), logging_listeners());
281	    }
