288	    void fetch_account(AccountDone done) override
289	    {
290	        for (const std::string& provider : configured_providers()) {
291	            const ProviderProfile* profile = profile_for(provider);
292	            if (profile == nullptr || !profile->account_sign_in)
293	                continue;
294	            Agent::fetch_account(*profile, load_provider_api_key(m_config, provider), endpoint_for(m_config, *profile), m_cancelled,
295	                                 [post = m_post, done = std::move(done)](std::optional<nlohmann::json> account) {
296	                                     post([done, account = std::move(account)]() mutable { done(std::move(account)); });
297	                                 });
298	            return;
299	        }
300	        done(std::nullopt);
301	    }
302	
303	    void list_models(const std::string& provider, ModelsDone done) override
304	    {
305	        const ProviderProfile* profile = profile_for(provider);
306	        const std::string      key     = load_provider_api_key(m_config, provider);
307	        if (profile == nullptr || key.empty()) {
308	            done(false, {});
309	            return;
310	        }
311	        fetch_model_list(*profile, key, endpoint_for(m_config, *profile), m_cancelled,
312	                         [post = m_post, done = std::move(done), provider, config = m_config,
313	                          account = profile->account_sign_in](ModelListResult result) {
314	                             if (!result.ok)
315	                                 BOOST_LOG_TRIVIAL(warning) << "Agent model list for " << provider << ": " << result.error;
316	                             post([done, result = std::move(result), provider, config, account]() mutable {
317	                                 // An account's list says which format each model
318	                                 // is served in now; chats not yet started go by it.
319	                                 if (account && result.ok && config != nullptr) {
320	                                     std::vector<std::pair<std::string, std::string>> formats;
321	                                     for (const ModelOption& option : result.models)
322	                                         formats.emplace_back(option.id, option.format);
323	                                     store_formats(config, provider, formats);
324	                                     config->save();
325	                                 }
326	                                 done(result.ok, std::move(result.models));
327	                             });
328	                         });
329	    }
