1245	        const double scale = double(kReportThumbnailPixels) / std::max(image.GetWidth(), image.GetHeight());
1246	        image.Rescale(std::max(1, int(image.GetWidth() * scale)), std::max(1, int(image.GetHeight() * scale)), wxIMAGE_QUALITY_HIGH);
1247	        wxMemoryOutputStream stream;
