1258	void OrcaHomeBackend::send_print_report(const PrintReportForm& form, std::function<void(const PrintReportAnswer&)> done)
1259	{
1260	    const Agent::GcodeRecord* record = nullptr;
1261	    std::string               project_name;
1262	    for (const HistoryProject& project : m_history)
1263	        if (project.id == form.project_id)
1264	            for (const Agent::GcodeRecord& candidate : project.records)
1265	                if (candidate.hash == form.hash) {
1266	                    record       = &candidate;
1267	                    project_name = project.name;
1268	                }
1269	    if (record == nullptr)
1270	        throw std::logic_error("a print report names G-code " + form.hash + ", which project " + form.project_id + " does not hold");
1271	    const std::filesystem::path photo = std::filesystem::u8path(m_report_photos.at(form.photo_id));
1272	
1273	    AppConfig* config  = wxGetApp().app_config;
1274	    const auto finish  = [this, alive = std::weak_ptr<void>(m_alive), form, done = std::move(done)](unsigned status, const std::string& body) {
1275	        PrintReportAnswer answer = print_report_answer(status, body);
1276	        if (answer.state == PrintReportAnswer::State::Failed)
1277	            BOOST_LOG_TRIVIAL(warning) << "Print report for G-code " << form.hash << " answered " << status;
1278	        wxGetApp().CallAfter([this, alive, form, done, answer] {
1279	            if (alive.expired())
1280	                return;
1281	            ShellController* shell = installed_shell();
1282	            if (answer.state != PrintReportAnswer::State::Failed && shell != nullptr && shell->gcode_history() != nullptr)
1283	                shell->gcode_history()->record_report(form.project_id, form.hash, answer.credits);
1284	            done(answer);
1285	        });
1286	    };
1287	    Http::post(Agent::cloud_print_reports_url(config))
1288	        .header("Authorization", "Bearer " + Agent::cloud_account_token(config))
1289	        .form_add("gcode_hash", form.hash)
1290	        .form_add("outcome", form.outcome)
1291	        .form_add("text", form.text)
1292	        .form_add("facts", report_facts(project_name, *record, history_facts()).dump())
1293	        .form_add_file("photos", boost::filesystem::path(photo.native()))
1294	        .tls_verify(true)
1295	        .timeout_connect(10)
1296	        .timeout_max(kReportUploadSeconds)
1297	        .on_complete([finish](std::string body, unsigned status) { finish(status, body); })
1298	        .on_error([finish](std::string body, std::string, unsigned status) { finish(status, body); })
1299	        .perform();
